style.css:
/* Midnight Silver Arrow — Google */

:root {
  --my-midnight: #101923;
  --my-navy: #1b2a39;
  --my-silver: #bdc5ca;
  --my-burgundy: #762d3b;
  --my-text: #e5e0d6;
}

/* midnight background and car photograph */
body {
  background-color: var(--my-midnight) !important;
  background-image:
    linear-gradient(
      to bottom,
      rgba(16, 25, 35, 0.12),
      rgba(16, 25, 35, 0.5) 100%
    ),
    url("https://silodrome.com/wp-content/uploads/2022/01/Mercedes-Benz-300-SL-Alloy-Gullwing.jpg") !important;
  background-size: 100% 300px, auto 300px !important;
  background-position: center top, center top !important;
  background-repeat: no-repeat !important;
  color: var(--my-text) !important;
  font-family: Georgia, "Times New Roman", serif !important;
}

/* Google text */
a {
  color: #c5a5ad !important;
}

/* search box */
input:not([type="checkbox"]):not([type="radio"]),
textarea {
  background-color: #202c37 !important;
  color: var(--my-text) !important;
  border: 1px solid var(--my-silver) !important;
  border-radius: 24px !important;
}

/* buttons */
button {
  background-color: #202c37 !important;
  color: var(--my-text) !important;
  border: 1px solid #667783 !important;
  border-radius: 8px !important;
}

/* selection */
::selection {
  background: var(--my-burgundy) !important;
  color: white !important;
}
